{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "평소와 다른 처방이 필요한 증량일 수도 있는 상황에서 투약보다 처방 확인을 우선하는 판단을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동에서 수술 후 환자의 진통제가 평소 두 배 용량으로 처방되었다.",
          "task": "처방 용량이 의심되는 상황에서 투약을 진행해도 되는지 판단해야 했다.",
          "action": "용량의 타당성이 확인되지 않은 상태에서 투약을 멈추고 담당의에게 확인했다.",
          "result": "담당의 확인으로 입력 오류를 발견해 잘못된 용량의 투약을 막았다."
        },
        "expectedEvidence": [
          "필요한 증량일 가능성만으로 투약을 진행할 수 없었던 이유를 설명한다.",
          "당시 처방 용량의 타당성을 확신할 수 없었던 사정을 짚는다.",
          "투약을 보류하고 담당의에게 확인해 입력 오류를 발견한 사실을 제시한다."
        ]
      },
      "question": "푸른결종합병원에서 평소 두 배의 진통제 처방에 투약을 멈추셨던데요. 환자에게 필요한 증량일 가능성에도 투약을 멈춰야 했던 이유는 무엇이었나요?",
      "answerTip": "당시 판단을 구체적으로 떠올려 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "필요한 증량과 입력 오류를 구분할 근거가 부족했음을 당시 상황에 연결해 설명한다.",
            "확인 전 투약의 위험을 근거로 중단을 설명하고 담당의에게 입력 오류를 확인한 사실을 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "의심스러운 처방은 확인해야 한다고 답하지만 당시 중단 판단의 근거는 일반적인 안전 원칙에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 멈춘 이유를 설명하지 못하거나 의심되는 처방도 확인 없이 수행해야 한다고 답한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "교대 시간대 낙상 양상을 바탕으로 다음 근무자에게 전달할 정보를 구체화한 판단을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 첫 보행 환자의 낙상이 근무 교대 시간대에 집중되어 있었다.",
          "task": "다음 근무자가 환자 상태를 이어서 관찰할 수 있도록 인수인계 정보를 정해야 했다.",
          "action": "진통제 투여 시각을 전달해야 하는 이유를 환자 상태 관찰의 연속성과 연결했다.",
          "result": "다음 근무자가 투여 이후의 환자 상태 변화를 이어서 판단할 수 있다."
        },
        "expectedEvidence": [
          "투여 여부만이 아니라 투여 시각을 전달해야 하는 이유를 설명한다.",
          "투여 시각이 다음 근무자의 환자 상태 관찰에 쓰이는 지점을 구체적으로 짚는다."
        ]
      },
      "question": "푸른결종합병원에서 진통제 투여 시각을 인수인계표에 넣어 분기 낙상을 5건에서 2건으로 줄이셨던데요. 투여 여부보다 시각을 전달하는 게 중요한 이유는 무엇인가요?",
      "answerTip": "질문에서 묻는 차이에 초점을 맞춰 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "투여 여부만으로는 알 수 없는 시간 정보를 환자 상태 변화와 연결해 설명한다.",
            "다음 근무자가 투여 시각을 바탕으로 이어서 관찰할 지점을 구체적으로 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "투여 시각을 전달할 필요성은 설명하지만 다음 근무자의 상태 관찰과 연결하는 근거가 막연하다."
          ]
        },
        "poor": {
          "criteria": [
            "투여 시각을 전달해야 하는 이유를 설명하지 못하거나 낙상 감소 수치만 반복한다."
          ]
        }
      }
    }
  ]
}

